{
  "mechanisms": [
    {
      "name": "asymmetric_rl_learning_rates",
      "title": "Asymmetric RL Learning Rates",
      "description": "Reinforcement learning updates use separate learning rates for rewarded and unrewarded trials.",
      "params": [
        {
          "name": "lr_pos",
          "bounds": [0, 1]
        },
        {
          "name": "lr_neg",
          "bounds": [0, 1]
        }
      ],
      "evidence": "lr = lr_pos if r > 0.5 else lr_neg\ndelta = r - Q_s[a]\nq[s, a] += lr * delta",
      "expressible_in_slots": true
    },
    {
      "name": "set_size_wm_decay",
      "title": "Set-Size Dependent WM Decay",
      "description": "Working memory values decay toward a uniform distribution at a rate that exponentially approaches 1 as set size increases.",
      "params": [
        {
          "name": "gamma",
          "bounds": [0, null]
        }
      ],
      "evidence": "phi = 1.0 - np.exp(-gamma * float(nS))\n...\nw[s, :] = (1.0 - phi) * w[s, :] + phi * w_0[s, :]",
      "expressible_in_slots": true
    },
    {
      "name": "set_size_wm_noise",
      "title": "Set-Size Dependent WM Noise",
      "description": "The working memory policy becomes noisier (lower inverse temperature) as the set-size dependent interference increases.",
      "params": [
        {
          "name": "gamma",
          "bounds": [0, null]
        }
      ],
      "evidence": "eff_beta_wm = max(1.0, softmax_beta_wm * (1.0 - 0.8 * phi))\n...\ndenom_wm = np.sum(np.exp(eff_beta_wm * (W_s - W_s[a])))",
      "expressible_in_slots": true
    },
    {
      "name": "wm_perfect_encoding_on_reward",
      "title": "Perfect WM Encoding on Reward",
      "description": "Working memory perfectly encodes the chosen action as a sharp distribution when a reward is received, overriding previous values.",
      "params": [],
      "evidence": "if r > 0.5:\n    w[s, :] = 0.0\n    w[s, a] = 1.0",
      "expressible_in_slots": true
    }
  ]
}
